 'PATCH /timekeeping/shifts/:id':{permissionGroups:[['timekeeping:manage']],safeCompanyScopedPath:true,pathReferences:{id:'api.get.d632a938b9c72492'},pathLabels:{id:'Tên hoặc mã ca cần cập nhật'},body:partial(object(shiftFields)),title:'Cập nhật ca làm việc',description:'Cập nhật riêng các thông tin được nêu của ca đã chọn theo tên hoặc mã; trường khác được giữ nguyên. Thay đổi ca có thể ảnh hưởng đến nhân viên đang được phân công. Cần xác nhận.',confirmation:true,resultFields:['name','code','startTime','endTime','workingDaysLabel','isDefault','isActive'],evidence:'server/router/timekeeping.router.ts, server/controller/work-shift.controller.ts, server/model/work-shift.model.ts'},
