 'POST /payroll/policies':{id:'payroll.policy.create',permissionGroups:[['payroll-policy:manage']],body:payrollPolicyDefinition,title:'Tạo chính sách lương',description:'Tạo chính sách lương ở trạng thái nháp. Cần ngày hiệu lực, mức lương cơ sở, mức lương tối thiểu vùng, các quỹ bảo hiểm, giảm trừ, bậc thuế và hệ số làm thêm. Có thể dùng mức Việt Nam mặc định khi nêu rõ; trợ lý sẽ hỏi các mức còn thiếu. Cần xác nhận trước khi lưu.',confirmation:true,dateOnlyToIsoUtc:['effectiveFrom','effectiveTo'],resultFields:['code','name','effectiveFrom','effectiveTo','baseSalary','regionalMinimumWage','status','version'],evidence:'server/router/payroll.router.ts, server/controller/payroll.controller.ts, server/validation/payroll-run.validation.ts, server/service/payroll-policy-operations.service.ts'},
