 'GET /payroll/runs/:id/payments':{id:'payroll.run.payments.list',permissionGroups:[['payroll-payment:read']],pathReferences:{id:'payroll.run.list'},pathLabels:{id:'Lượt lương cần tra cứu khoản thanh toán'},title:'Tra cứu các đợt thanh toán lương',description:'Liệt kê trạng thái và tổng tiền của các đợt thanh toán trong lượt lương đã chọn theo kỳ và chi nhánh. Chỉ hiển thị tổng tiền, trạng thái, ngày thanh toán, thời điểm tạo và số nhân viên; không hiển thị ghi chú tự do, mã thanh toán, mã nhân viên, chi tiết từng dòng, bằng chứng hay dữ liệu kiểm toán. Cần quyền đọc thanh toán lương.',resultFields:['amount','status','paymentDate','createdAt','employeeCount'],evidence:'server/router/payroll.router.ts, server/controller/payroll.controller.ts, server/model/payroll-payment.model.ts'},
