 'POST /payroll/payments/:id/confirm':{id:'payroll.payment.confirm',permissionGroups:[['payroll-payment:manage'],['payroll-payment:read'],['payroll-period:read','payroll-period:manage'],['access:read']],pathReferences:{id:'payroll.run.payments.list'},pathLabels:{id:'Đợt nháp đã chuyển tiền thực tế theo tổng tiền và ngày'},pathReferenceParentKeys:{id:'query_id'},query:object({id:{...text(true),reference:'payroll.run.list',referenceValueKey:'id',label:'Lượt lương (chọn theo kỳ và trạng thái)'},branchId:{...text(true),apiKey:'branchId',reference:'branch.list',label:'Chi nhánh của lượt lương'}}),contextBody:['correlationId'],dateOnlyToIsoUtc:['paymentDate'],body:object({paymentDate:{type:'date',required:true,label:'Ngày đã chuyển tiền thực tế'},note:{...text(true),max:1000,label:'Ghi chú đối chiếu giao dịch thực tế'}}),title:'Xác nhận đợt thanh toán lương đã chuyển tiền',description:'Chỉ ghi nhận khoản chuyển tiền lương đã thực hiện bên ngoài hệ thống; API không gửi lệnh ngân hàng. Chỉ xác nhận đợt đang nháp thuộc lượt đã chốt, còn số dư đủ và phân bổ khớp từng nhân viên. Bắt buộc nêu ngày chuyển tiền và ghi chú đã đối chiếu giao dịch thực tế; yêu cầu quyền quản lý và đọc thanh toán lương, quyền tra cứu lượt, chọn chi nhánh nếu cần và xác nhận.',confirmation:true,resultFields:['status','amount','employeeCount','paymentDate','runStatus'],evidence:'server/router/payroll.router.ts, server/controller/payroll.controller.ts, server/validation/payroll-run.validation.ts, server/service/payroll-payment-operations.service.ts, server/service/payroll-payment.service.ts'},
 'POST /payroll/payments/:id/reverse':{id:'payroll.payment.reverse',permissionGroups:[['payroll-payment:manage'],['payroll-payment:read'],['payroll-period:read','payroll-period:manage'],['access:read']],pathReferences:{id:'payroll.run.payments.list'},pathLabels:{id:'Đợt đã xác nhận cần đảo theo tổng tiền, ngày và trạng thái'},pathReferenceParentKeys:{id:'query_id'},query:object({id:{...text(true),reference:'payroll.run.list',referenceValueKey:'id',label:'Lượt lương (chọn theo kỳ và trạng thái)'},branchId:{...text(true),apiKey:'branchId',reference:'branch.list',label:'Chi nhánh của lượt lương'}}),contextBody:['correlationId'],body:object({note:{...text(true),max:1000,label:'Lý do đảo xác nhận thanh toán'}}),title:'Đảo xác nhận đợt thanh toán lương',description:'Đảo trạng thái sổ thanh toán đã xác nhận về khoản chưa thanh toán; API chỉ điều chỉnh sổ lương, không thu hồi tiền từ ngân hàng. Chỉ cho khoản đã xác nhận trong lượt đang chốt/đã thanh toán và chưa bị đảo. Cần quyền quản lý và đọc thanh toán lương, quyền tra cứu lượt, chọn chi nhánh nếu cần, nêu lý do và xác nhận.',confirmation:true,resultFields:['status','amount','employeeCount','runStatus'],evidence:'server/router/payroll.router.ts, server/controller/payroll.controller.ts, server/validation/payroll-run.validation.ts, server/service/payroll-payment-operations.service.ts, server/service/payroll-payment.service.ts'},
 'POST /payroll/runs/:id/payslips/publish':{id:'payroll.run.payslips.publish',permissionGroups:[['payroll-payment:manage'],['payroll-period:read','payroll-period:manage']],safeCompanyScopedPath:true,pathReferences:{id:'payroll.run.list'},pathLabels:{id:'Lượt lương đã chốt cần công bố phiếu'},body:object({}),title:'Công bố phiếu lương trong ứng dụng',description:'Công bố phiếu lương cho toàn bộ nhân viên có dòng lương hợp lệ trong lượt đã chốt hoặc đã thanh toán. Thao tác chỉ bật phiếu để nhân viên xem trong ứng dụng, không gửi tiền hay gửi email. Cần quyền quản lý thanh toán lương và quyền tra cứu lượt lương; yêu cầu xác nhận trước khi công bố. Kết quả chỉ trả số lượng phiếu.',confirmation:true,resultFields:['publishedCount'],evidence:'server/router/payroll.router.ts, server/controller/payroll.controller.ts, server/model/payroll-run.model.ts'},
 'POST /payroll/runs/:id/payslips/:employeeId/withdraw':{id:'payroll.run.payslips.withdraw',permissionGroups:[['payroll-payment:manage'],['payroll-period:read','payroll-period:manage'],['access:read','hr:read']],safeCompanyScopedPath:true,pathReferences:{id:'payroll.run.list',employeeId:'employee.list'},pathLabels:{id:'Lượt lương có phiếu cần thu hồi',employeeId:'Tên nhân viên cần thu hồi phiếu'},body:object({}),title:'Thu hồi phiếu lương đã công bố',description:'Thu hồi phiếu lương đang công bố cho một nhân viên được chọn theo tên trong lượt lương đã chọn theo kỳ và chi nhánh. API chỉ đổi trạng thái phiếu đã công bố sang đã thu hồi; không thay đổi dữ liệu lương hay thanh toán. Cần quyền quản lý thanh toán lương và quyền tra cứu lượt lương, nhân sự; yêu cầu xác nhận.',confirmation:true,resultFields:['withdrawn'],evidence:'server/router/payroll.router.ts, server/controller/payroll.controller.ts, server/model/payroll-run.model.ts'},
  'GET /payroll/runs/:id/lines/:employeeId':{id:'payroll.run.line.detail',permissionGroups:[['payroll-period:read','payroll-period:manage'],['payroll-payment:read','payroll-payment:manage'],['access:read','hr:read']],safeCompanyScopedPath:true,pathReferences:{id:'payroll.run.list',employeeId:'employee.list'},pathLabels:{id:'Lượt chạy lương cần xem',employeeId:'Tên nhân viên cần xem'},title:'Xem chi tiết lương nhân viên',description:'Xem tổng thu nhập, khấu trừ và thực nhận của một nhân viên trong lượt lương đã chọn theo tên. Cần quyền xem thanh toán lương và nhân sự, đồng thời chọn chi nhánh nếu tài khoản quản trị chưa gắn chi nhánh. Kết quả không chứa ID nhân viên, tài khoản ngân hàng, công thức hay dữ liệu kiểm toán.',resultFields:['employeeName','grossPay','deductions','netPay'],evidence:'server/router/payroll.router.ts, server/controller/payroll.controller.ts, server/service/payroll-effective-line.service.ts'},
