 'POST /partners':{body:object({name:text(true),phone:text(true),email:text(),commissionType:text(false,['percentage','fixed']),commissionValue:number(false),bankName:text(),bankAccountNo:text(),bankAccountName:text(),isActive:{type:'boolean'},notes:text(),customFields:{type:'object',keys:{},open:true}}),title:'Tạo đối tác giới thiệu',description:'Tạo đối tác giới thiệu học viên. Cần tên và số điện thoại; hình thức hoa hồng là percentage (phần trăm) hoặc fixed (số tiền VND). Cần xác nhận trước khi lưu.',resultFields:['name','phone','email','bankName','bankAccountNo','bankAccountName','commissionType','commissionValue','isActive'],evidence:'server/modules/student-management/validations/partner.validation.ts'},
