 'POST /worker-management/partners/policies':{body:laborPartnerPolicy,title:'Tạo chính sách hoa hồng đối tác lao động',description:'Tạo chính sách hoa hồng cho một loại lao động: chính thức hoặc thời vụ. Cần cho người dùng chọn loại lao động trước, sau đó chỉ hỏi cấu hình riêng của loại đã chọn. Các thông tin chung gồm tên, ngày áp dụng và chu kỳ đối soát. Với lao động chính thức, số tháng phải khớp số mốc đã khai báo; với lao động thời vụ, cần phạm vi tổng hợp, cách tính bậc và ít nhất một bậc giờ cuối không giới hạn. Chính sách mới được kích hoạt sau khi lưu. Hãy hỏi thông tin còn thiếu; thao tác cần xác nhận.',resultFields:['name','version','effectiveFrom','effectiveTo','status','settlementCycle','official','seasonal'],evidence:'server/modules/worker-management/labor-partners/validations/commission-policy.validation.ts'},
 'GET /worker-management/partners/policies/:policyId':{title:'Xem chính sách hoa hồng đối tác lao động',resultFields:['name','version','effectiveFrom','effectiveTo','status','settlementCycle','official','seasonal'],evidence:'server/modules/worker-management/labor-partners/services/commission-policy.service.ts'},
 'PATCH /worker-management/partners/policies/:policyId':{body:laborPartnerPolicy,title:'Cập nhật chính sách hoa hồng đối tác lao động',description:'Thay thế toàn bộ cấu hình của chính sách đã chọn theo tên hoặc mã. Cần gửi đủ chu kỳ đối soát và cấu hình hoa hồng chính thức, thời vụ; trạng thái áp dụng quyết định cấu hình tương ứng. Nếu chính sách đang ngừng, hệ thống sẽ kích hoạt lại sau khi cập nhật. Hãy hỏi thông tin còn thiếu; cần xác nhận trước khi ghi.',resultFields:['name','version','effectiveFrom','effectiveTo','status','settlementCycle','official','seasonal'],evidence:'server/modules/worker-management/labor-partners/validations/commission-policy.validation.ts'},
 'POST /worker-management/partners/policies/:policyId/activate':{body:object({}),title:'Kích hoạt chính sách hoa hồng đối tác lao động',description:'Kích hoạt chính sách đang ở trạng thái nháp hoặc đã ngừng. API từ chối trạng thái khác; cần xác nhận.',resultFields:['name','version','status','activatedAt'],evidence:'server/modules/worker-management/labor-partners/services/commission-policy.service.ts'},
