 'POST /retail/after-sales/reconcile':{assistantUnsupported:'C\u1EA7n kh\u1EDBp idempotencyKey v\u00E0 requestFingerprint c\u1EE7a l\u1EA7n t\u1EA1o g\u1ED1c c\u00F9ng to\u00E0n b\u1ED9 payload; kh\u00F4ng c\u00F3 danh s\u00E1ch y\u00EAu c\u1EA7u \u0111\u1EC3 ng\u01B0\u1EDDi d\u00F9ng ch\u1ECDn theo t\u00EAn. D\u00F9ng trong lu\u1ED3ng kh\u00F4i ph\u1EE5c g\u1EAFn v\u1EDBi l\u1EA7n t\u1EA1o, kh\u00F4ng g\u1ECDi nh\u01B0 t\u00E1c v\u1EE5 th\u01B0\u1EDDng.'},
 'POST /retail/after-sales/revoke':{assistantUnsupported:'T\u1EA1o gate thu h\u1ED3i y\u00EAu c\u1EA7u ph\u1EA3i d\u00F9ng ch\u00EDnh idempotencyKey v\u00E0 payload c\u1EE7a l\u1EA7n t\u1EA1o g\u1ED1c; sai payload c\u00F3 th\u1EC3 xung \u0111\u1ED9t v\u1EDBi phi\u1EBFu h\u1EE3p l\u1EC7. Ch\u01B0a c\u00F3 workflow kh\u00F4i ph\u1EE5c g\u1EAFn v\u1EDBi phi\u00EAn t\u1EA1o v\u00E0 x\u00E1c nh\u1EADn ri\u00EAng.'},
